mapper.select:
SELECT LOAN_NO, PRODUCT_NM, BANK_CD, BANK_NM, ACCOUNT_NO, ACCOUNT_TYPE
  FROM TB_LOAN_ACCOUNT
 WHERE MEMBER_ID = #{memberId} AND LOAN_NO = #{loanNo}

SELECT , b.BIZ_NM, b.SCREEN_TYPE
  FROM TB_CO_ACCT_VERIFY r
  LEFT JOIN TB_CO_ACCT_BIZ b ON b.BIZ_CD = r.BIZ_CD

    AND r.BIZ_CD = #{bizCd}
    AND r.STATUS = #{status}

 ORDER BY r.REQ_AT DESC
 LIMIT #{limit}
